45	        durableObject: pong,
46	        hasAnthropicKey: Boolean(env.ANTHROPIC_API_KEY),
47	        secretGate: env.APP_SECRET ? "enabled" : "open",
48	      });
49	    }
50	
51	    // POST /api/session — mint a session id. The DO is created lazily on first use.
52	    if (url.pathname === "/api/session") {
53	      if (request.method !== "POST") return json({ error: "method not allowed" }, 405);
54	      const body: CreateSessionResponse = { sessionId: crypto.randomUUID() };
55	      return json(body);
56	    }
57	
58	    // /api/session/:id[/action]
59	    const parts = url.pathname.split("/").filter(Boolean); // ["api","session",id,action?]
60	    if (parts[0] === "api" && parts[1] === "session" && parts[2]) {
61	      const sessionId = parts[2];
62	      const action = parts[3];
63	      const session = env.SESSION.getByName(sessionId);
64	
65	      try {
66	        if (!action) {
67	          if (request.method !== "GET") return json({ error: "method not allowed" }, 405);
68	          return json(await session.snapshot());
69	        }
70	
71	        if (request.method !== "POST") return json({ error: "method not allowed" }, 405);
72	
73	        switch (action) {
74	          case "target": {
75	            const body = await readJson<SetTargetRequest>(request);
76	            if (!body?.features || !body?.info) {
77	              return json(errorStep("Missing features or info."), 400);
78	            }
79	            return json(await session.setTarget(body.features, body.info));
80	          }
81	          case "analysis": {
82	            const body = await readJson<SubmitAnalysisRequest>(request);
83	            if (!body?.presetId || !body?.features || !body?.diff) {
84	              return json(errorStep("Missing presetId, features or diff."), 400);
85	            }
86	            return json(await session.submitAnalysis(body.presetId, body.features, body.diff));
87	          }
88	          case "render-error": {
89	            const body = await readJson<SubmitRenderErrorRequest>(request);
90	            if (!body?.presetId) return json(errorStep("Missing presetId."), 400);
91	            return json(await session.submitRenderError(body.presetId, String(body.message ?? "")));
92	          }
93	          case "chat": {
94	            const body = await readJson<ChatRequest>(request);
95	            if (!body?.message?.trim()) return json(errorStep("Missing message."), 400);
96	            return json(await session.chat(body.message));
97	          }
98	          default:
99	            return json({ error: "not found", path: url.pathname }, 404);
100	        }
101	      } catch (err) {
102	        // Stale presetId, wrong status, bad JSON — client-side problems. Always
103	        // answer with a Step so the client's drain loop can render it.
104	        return json(errorStep(err instanceof Error ? err.message : String(err)), 409);
105	      }
106	    }
107	
108	    return json({ error: "not found", path: url.pathname }, 404);
109	  },
110	} satisfies ExportedHandler<Env>;

