// Entry point. Full UI + drain loop land next; for now this establishes the
// session key handling so the deployed app isn't a bare 401.

const KEY_STORAGE = "claudio.appKey";

/** Key comes from ?k=<secret> once, then persists in localStorage. */
export function getAppKey(): string | null {
  const fromUrl = new URLSearchParams(location.search).get("k");
  if (fromUrl) {
    localStorage.setItem(KEY_STORAGE, fromUrl);
    // Strip it from the address bar so the secret isn't sitting in the URL.
    const clean = new URL(location.href);
    clean.searchParams.delete("k");
    history.replaceState({}, "", clean.toString());
    return fromUrl;
  }
  return localStorage.getItem(KEY_STORAGE);
}

/** Fetch wrapper that attaches the key as a header (never in the URL). */
export async function api(path: string, init: RequestInit = {}): Promise<Response> {
  const key = getAppKey();
  const headers = new Headers(init.headers);
  headers.set("content-type", "application/json");
  if (key) headers.set("x-app-key", key);
  return fetch(path, { ...init, headers });
}

function promptForKey(message: string) {
  const app = document.getElementById("app");
  if (!app) return;
  app.innerHTML = `
    <h1>Claudio</h1>
    <p>${message}</p>
    <form id="keyform">
      <input id="keyinput" type="password" placeholder="app key" autocomplete="off" />
      <button type="submit">Unlock</button>
    </form>
    <p style="opacity:.6">Or open this page once as <code>?k=&lt;key&gt;</code>.</p>`;
  document.getElementById("keyform")?.addEventListener("submit", (e) => {
    e.preventDefault();
    const v = (document.getElementById("keyinput") as HTMLInputElement).value.trim();
    if (!v) return;
    localStorage.setItem(KEY_STORAGE, v);
    location.reload();
  });
}

async function boot() {
  const res = await api("/api/ping");
  if (res.status === 401) {
    localStorage.removeItem(KEY_STORAGE);
    promptForKey("This deployment is key-gated. Enter the app key to continue.");
    return;
  }
  const body = await res.json();
  const el = document.getElementById("boot");
  if (el) el.textContent = JSON.stringify(body);
}

boot().catch((e) => {
  const el = document.getElementById("boot");
  if (el) el.textContent = `boot failed: ${String(e)}`;
});

