s=s.replace('import { PRESET_JSON_SCHEMA, RANGE } from "../shared/preset";',
            'import { PRESET_JSON_SCHEMA, RANGE } from "../shared/preset";\nimport { SUGGESTION_COUNT } from "../shared/protocol";')
open(p,'w').write(s)

# 2. session.ts readToolInput returns suggestions too
p='src/worker/session.ts'; s=open(p).read()
s=s.replace('''function readToolInput(input: unknown): { preset: ClaudioPreset; rationale: string } {
  const obj = (input ?? {}) as { preset?: unknown; rationale?: unknown };
  return {
    preset: clampPreset(obj.preset),
    rationale: typeof obj.rationale === "string" ? obj.rationale : "",
  };
}''','''function readToolInput(input: unknown): {
  preset: ClaudioPreset;
  rationale: string;
  suggestions: string[];
} {
  const obj = (input ?? {}) as { preset?: unknown; rationale?: unknown; suggestions?: unknown };
  // Agent-authored, so treat as untrusted: strings only, trimmed, capped in
  // both count and length so a runaway response can't wreck the chip row.
  const suggestions = Array.isArray(obj.suggestions)
    ? obj.suggestions
        .filter((s): s is string => typeof s === "string")
        .map((s) => s.trim())
        .filter(Boolean)
        .slice(0, SUGGESTION_COUNT)
        .map((s) => (s.length > 48 ? `${s.slice(0, 47)}…` : s))
    : [];
  return {
    preset: clampPreset(obj.preset),
    rationale: typeof obj.rationale === "string" ? obj.rationale : "",
    suggestions,
  };
}''')
open(p,'w').write(s)
