1	import { DurableObject } from "cloudflare:workers";
2	import type Anthropic from "@anthropic-ai/sdk";
3	
4	import { clampPreset, type ClaudioPreset } from "../shared/preset";
5	import type { FeatureDiff, FeatureSummary } from "../shared/features";
6	import {
7	  MAX_ITERATIONS,
8	  type Attempt,
9	  type SessionSnapshot,
10	  type SessionStatus,
11	  type Step,
12	  type TargetInfo,
13	} from "../shared/protocol";
14	import { MissingApiKeyError, runClaude, type MessageParam } from "./agent";
15	
16	/**
17	 * One Durable Object per sound-design session.
18	 *
19	 * Holds the paused Anthropic conversation between HTTP round trips: the agent's
20	 * turn stops at a tool_use block, and can only be resumed once the browser has
21	 * rendered + analyzed the proposed preset. `pendingToolUseId` is what survives
22	 * that gap — on submitAnalysis we synthesize a tool_result carrying that exact
23	 * id, append it, and call the model again. See PLAN.md "The agent loop protocol".
24	 *
25	 * Two tables rather than one blob: the message log grows unboundedly across chat
26	 * turns and would eventually blow the 128 KiB per-value limit.
27	 */
28	
29	interface Meta {
30	  status: SessionStatus;
31	  target: FeatureSummary | null;
32	  targetInfo: TargetInfo | null;
33	  iteration: number;
34	  maxIterations: number;
35	  history: Attempt[];
36	  bestPresetId: string | null;
37	  bestDistance: number | null;
38	  /** The crux: the tool_use we owe a tool_result for. */
39	  pendingToolUseId: string | null;
40	  pendingPresetId: string | null;
41	}
42	
43	const freshMeta = (): Meta => ({
44	  status: "idle",
45	  target: null,
46	  targetInfo: null,
47	  iteration: 0,
48	  maxIterations: MAX_ITERATIONS,
49	  history: [],
50	  bestPresetId: null,
51	  bestDistance: null,
52	  pendingToolUseId: null,
53	  pendingPresetId: null,
54	});
55	
56	interface ToolCall {
57	  id: string;
58	  name: string;
59	  input: unknown;
60	}
61	
62	/** Thrown for client mistakes (stale presetId, wrong status) — mapped to 409. */
63	export class ProtocolError extends Error {
64	  constructor(message: string) {
65	    super(message);
66	    this.name = "ProtocolError";
67	  }
68	}
69	
70	export class SessionDO extends DurableObject<Env> {
71	  private meta: Meta = freshMeta();
72	  private messages: MessageParam[] = [];
73	
74	  constructor(ctx: DurableObjectState, env: Env) {
75	    super(ctx, env);
76	    ctx.blockConcurrencyWhile(async () => {
77	      this.ctx.storage.sql.exec(
78	        `CREATE TABLE IF NOT EXISTS meta (
79	           id INTEGER PRIMARY KEY CHECK(id = 1),
80	           json TEXT NOT NULL
81	         );`,
82	      );
83	      this.ctx.storage.sql.exec(
84	        `CREATE TABLE IF NOT EXISTS messages (
85	           seq INTEGER PRIMARY KEY AUTOINCREMENT,
86	           json TEXT NOT NULL
87	         );`,
88	      );
89	
90	      const metaRows = [
91	        ...this.ctx.storage.sql.exec<{ json: string }>(`SELECT json FROM meta WHERE id = 1`),
92	      ];
93	      if (metaRows.length > 0) {
94	        this.meta = { ...freshMeta(), ...(JSON.parse(metaRows[0].json) as Partial<Meta>) };
95	      }
96	
97	      const msgRows = [
98	        ...this.ctx.storage.sql.exec<{ json: string }>(`SELECT json FROM messages ORDER BY seq ASC`),
99	      ];
100	      this.messages = msgRows.map((row) => JSON.parse(row.json) as MessageParam);
101	    });
102	  }
103	
104	  /** Liveness probe used by /api/ping so we exercise the DO binding end to end. */
105	  async ping(): Promise<{ ok: true; id: string }> {
106	    return { ok: true, id: this.ctx.id.toString() };
107	  }
108	
109	  // -------------------------------------------------------------------------
110	  // Persistence helpers. Never held across a network call.
111	  // -------------------------------------------------------------------------
112	
113	  private saveMeta(): void {
114	    this.ctx.storage.sql.exec(
115	      `INSERT INTO meta (id, json) VALUES (1, ?)
116	       ON CONFLICT(id) DO UPDATE SET json = excluded.json`,
117	      JSON.stringify(this.meta),
118	    );
119	  }
120	
121	  private appendMessage(message: MessageParam): void {
122	    this.messages.push(message);
123	    this.ctx.storage.sql.exec(`INSERT INTO messages (json) VALUES (?)`, JSON.stringify(message));
124	  }
125	
126	  // -------------------------------------------------------------------------
127	  // RPC surface
128	  // -------------------------------------------------------------------------
129	
130	  async snapshot(): Promise<SessionSnapshot> {
131	    return {
132	      sessionId: this.ctx.id.toString(),
133	      status: this.meta.status,
134	      target: this.meta.target,
135	      targetInfo: this.meta.targetInfo,
136	      iteration: this.meta.iteration,
137	      maxIterations: this.meta.maxIterations,
138	      history: this.meta.history,
139	      bestPresetId: this.meta.bestPresetId,
140	    };
141	  }
142	
143	  async setTarget(features: FeatureSummary, info: TargetInfo): Promise<Step> {
144	    this.meta = {
145	      ...freshMeta(),
146	      status: "thinking",
147	      target: features,
148	      targetInfo: info,
149	    };
150	    // A re-upload starts a new conversation; the old message log is dead weight
151	    // and its tool_use ids no longer mean anything.
152	    this.messages = [];
153	    this.ctx.storage.sql.exec(`DELETE FROM messages`);
154	    this.saveMeta();
155	
156	    this.appendMessage({
157	      role: "user",
158	      content: [
159	        {
160	          type: "text",
161	          text:
162	            `The user uploaded "${info.filename}" (${info.durationSec.toFixed(2)}s @ ${info.sampleRate} Hz).\n` +
163	            `Here is its feature vector:\n\n` +
164	            "```json\n" +
165	            JSON.stringify(features) +
166	            "\n```\n\n" +
167	            `You have ${this.meta.maxIterations} render iterations. Pick an archetype that explains these ` +
168	            `features and instantiate it, then call propose_preset. The browser will render it and return a diff.`,
169	        },
170	      ],
171	    });
172	
173	    return await this.turn({ force: true, isFirstProposal: true });
174	  }
175	
176	  async submitAnalysis(presetId: string, features: FeatureSummary, diff: FeatureDiff): Promise<Step> {
177	    const toolUseId = this.requirePending(presetId);
178	
179	    // Record the measurement against the attempt it belongs to.
180	    const attempt = this.meta.history.find((a) => a.presetId === presetId);
181	    if (attempt) {
182	      attempt.features = features;
183	      attempt.distance = diff.distance;
184	    }
185	    if (this.meta.bestDistance === null || diff.distance < this.meta.bestDistance) {
186	      this.meta.bestDistance = diff.distance;
187	      this.meta.bestPresetId = presetId;
188	    }
189	
190	    this.meta.pendingToolUseId = null;
191	    this.meta.pendingPresetId = null;
192	    this.meta.status = "thinking";
193	    this.saveMeta();
194	
195	    const remaining = this.iterationsRemaining();
196	    this.appendMessage({
197	      role: "user",
198	      content: [
199	        {
200	          type: "tool_result",
201	          tool_use_id: toolUseId,
202	          content: JSON.stringify({
203	            distance: diff.distance,
204	            breakdown: diff.breakdown,
205	            verdict: diff.verdict,
206	            priorities: diff.priorities,
207	            scalars: diff.scalars,
208	            harmonics: diff.harmonics,
209	            iteration: this.meta.iteration,
210	            iterations_remaining: remaining,
211	            best_distance_so_far: this.meta.bestDistance,
212	            note:
213	              remaining <= 0
214	                ? "Iteration budget exhausted. You MUST call finalize now, with the BEST preset seen (lowest distance so far), not necessarily this one."
215	                : `Either propose the next preset with propose_preset (attack the largest weighted errors in priorities[], one or two changes, and say what you expect), or call finalize if this is good enough. You MUST call finalize when iterations_remaining reaches 0.`,
216	          }),
217	        },
218	      ],
219	    });
