1	/**
2	 * preset -> Tone mapping, plus the live (audible) voice.
3	 *
4	 * Topology (PLAN.md "Getting 4 operators out of a '2-operator' synth"):
5	 *
6	 *   op4 --(modulatorFm.index)--> op3 --(modulationIndex)--+
7	 *                                [modEnv]                 |
8	 *                                                         +--> op1 --> out
9	 *   op2 --(carrierFm.index)--------------------------------+   [ampEnv]
10	 *
11	 * One Tone.FMSynth. Its `oscillator` (op1) and `modulation` (op3) are each an
12	 * OmniOscillator; setting either to an `fm*` type turns it into a 2-op
13	 * FMOscillator with its own harmonicity/modulationIndex — op2 and op4.
14	 *
15	 * HARD RULE: build from a constructor options object, never by mutating after
16	 * construction. `harmonicity`/`modulationIndex` do not exist on an
17	 * OmniOscillator until its `type` has been set to an `fm*` variant, so mutation
18	 * ordering silently drops them.
19	 */
20	
21	import * as Tone from "tone";
22	import { clampPreset, DEFAULT_PRESET, type ClaudioPreset, type Wave } from "../../shared/preset";
23	
24	/** `RecursivePartial<Tone.FMSynthOptions>` — taken off the constructor so we
25	 *  don't depend on Tone re-exporting its internal `RecursivePartial` helper. */
26	export type FMSynthPartialOptions = NonNullable<ConstructorParameters<typeof Tone.FMSynth>[0]>;
27	
28	/** 0..1 linear -> Tone's dB `volume`. Floored so gain 0 can't produce -Infinity. */
29	export function gainToDb(gain: number): number {
30	  const g = Number.isFinite(gain) ? gain : 1;
31	  return 20 * Math.log10(Math.max(1e-4, g));
32	}
33	
34	/** MIDI note -> Hz. A4 (69) = 440. */
35	export function midiToHz(midi: number): number {
36	  return 440 * Math.pow(2, (midi - 69) / 12);
37	}
38	
39	/**
40	 * An operator pair: the host oscillator's own wave, plus its inner modulator.
41	 * `index === 0` collapses to a plain oscillator (`'sine'` rather than `'fmsine'`),
42	 * which is the documented meaning of index 0 in the preset schema.
43	 */
44	function oscOptions(wave: Wave, inner: { ratio: number; index: number }) {
45	  if (inner.index > 0) {
46	    return {
47	      type: `fm${wave}`,
48	      harmonicity: inner.ratio,
49	      modulationIndex: inner.index,
50	      modulationType: "sine",
51	      phase: 0,
52	    };
53	  }
54	  return { type: wave, phase: 0 };
55	}
56	
57	/**
58	 * The whole preset -> Tone translation. Pure; no nodes are created here.
59	 * Input is clamped first — the agent authors these numbers and a NaN written to
60	 * an AudioParam throws and permanently poisons the node.
61	 */
62	export function presetToOptions(p: ClaudioPreset): FMSynthPartialOptions {
63	  const c = clampPreset(p);
64	  const options = {
65	    // portamento 0 everywhere: offline it would glide into the note and corrupt
66	    // the attack-frame analysis; live it just isn't wanted.
67	    portamento: 0,
68	    volume: gainToDb(c.gain),
69	    detune: c.detune,
70	    harmonicity: c.harmonicity,
71	    modulationIndex: c.modulationIndex,
72	    oscillator: oscOptions(c.carrierWave, c.carrierFm),
73	    modulation: oscOptions(c.modulatorWave, c.modulatorFm),
74	    envelope: {
75	      attack: c.ampEnv.attack,
76	      decay: c.ampEnv.decay,
77	      sustain: c.ampEnv.sustain,
78	      release: c.ampEnv.release,
79	    },
80	    modulationEnvelope: {
81	      attack: c.modEnv.attack,
82	      decay: c.modEnv.decay,
83	      sustain: c.modEnv.sustain,
84	      release: c.modEnv.release,
85	    },
86	  };
87	  // The OmniOscillator options type is a 14-member union that TS cannot narrow
88	  // from a computed `type` string. One cast, per PLAN.md; the shape above is
89	  // exactly OmniFMTypeOscillatorOptions / ToneTypeOscillatorOptions.
90	  return options as unknown as FMSynthPartialOptions;
91	}
92	
93	/**
94	 * Construct the voice. NOTE: this uses whatever Tone context is current, which
95	 * is exactly what we want — called inside a `Tone.Offline` callback it builds an
96	 * offline node, called live it builds a live one. One code path, two contexts.
97	 */
98	export function buildVoice(p: ClaudioPreset): Tone.FMSynth {
99	  return new Tone.FMSynth(presetToOptions(p));
100	}
101	
102	// ---------------------------------------------------------------------------
103	// Live playback
104	// ---------------------------------------------------------------------------
105	
106	/**
107	 * The LIVE voice is polyphonic; the OFFLINE render deliberately is not.
108	 *
109	 * `buildVoice()` above returns a bare FMSynth and is what `Tone.Offline` uses —
110	 * the analysis renders exactly one note, and adding voices there would change
111	 * the thing being measured (and its level). Polyphony is a playing affordance,
112	 * not part of the measurement loop, so it lives only on this side.
113	 */
114	let liveVoice: Tone.PolySynth<Tone.FMSynth> | null = null;
115	let livePreset: ClaudioPreset | null = null;
116	let started = false;
117	
118	/**
119	 * Resume the live AudioContext. MUST be called from a user gesture handler
120	 * (click/keydown) — browsers reject it otherwise. Offline rendering does NOT
121	 * need this, so analysis and the first render can run before any click.
122	 */
123	export async function ensureAudio(): Promise<void> {
124	  if (started) return;
125	  await Tone.start();
126	  started = true;
127	}
128	
129	/**
130	 * Swap the live preset. Dispose + rebuild (~1ms) rather than mutating, so live
131	 * and offline share the single `presetToOptions` code path and can never drift.
132	 */
133	export function setLivePreset(p: ClaudioPreset): void {
134	  const c = clampPreset(p);
135	  livePreset = c;
136	  if (liveVoice) {
137	    liveVoice.dispose();
138	    liveVoice = null;
139	  }
140	  liveVoice = new Tone.PolySynth(Tone.FMSynth, presetToOptions(c)).toDestination();
141	  // Plenty for ten fingers; the cap only matters as a stealing backstop.
142	  liveVoice.maxPolyphony = 16;
143	}
144	
145	export function getLivePreset(): ClaudioPreset | null {
146	  return livePreset;
147	}
148	
149	/**
150	 * Audition a note. Requires `ensureAudio()` to have run at least once.
151	 * Falls back to building a voice on demand if none has been set.
152	 */
153	export function playNote(midi = 60, velocity = 0.9, durSec = 1.2): void {
154	  // Never silently do nothing: fall back to the init patch if the UI hasn't
155	  // pushed a preset yet.
156	  if (!liveVoice) setLivePreset(livePreset ?? DEFAULT_PRESET);
157	  const v = Math.min(1, Math.max(0.01, Number.isFinite(velocity) ? velocity : 0.9));
158	  const d = Math.min(4, Math.max(0.05, Number.isFinite(durSec) ? durSec : 1.2));
159	  const hz = midiToHz(Number.isFinite(midi) ? midi : 60);
160	  liveVoice!.triggerAttackRelease(hz, d, undefined, v);
161	}
162	
163	/**
164	 * Hold-to-sustain, for the on-screen keyboard.
165	 *
166	 * Tone.FMSynth is monophonic, so this is last-note-priority: a new noteOn
167	 * while one is held retriggers at the new pitch. Polyphony would mean
168	 * PolySynth and a voice pool, which is more than a playable octave needs.
169	 */
170	export function noteOn(midi: number, velocity = 0.9): void {
171	  if (!liveVoice) setLivePreset(livePreset ?? DEFAULT_PRESET);
172	  const v = Math.min(1, Math.max(0.01, Number.isFinite(velocity) ? velocity : 0.9));
173	  const hz = midiToHz(Number.isFinite(midi) ? midi : 60);
174	  liveVoice!.triggerAttack(hz, undefined, v);
175	}
176	
177	/** Release one note. Omit `midi` to release everything still sounding. */
178	export function noteOff(midi?: number): void {
179	  if (!liveVoice) return;
180	  if (midi === undefined) liveVoice.releaseAll();
181	  else liveVoice.triggerRelease(midiToHz(midi));
182	}
183	
184	/** Release every sounding note without tearing the voice down. */
185	export function stopLive(): void {
186	  if (liveVoice) liveVoice.releaseAll();
187	}
188	
189	/** Tear the live voice down entirely. */
190	export function disposeLive(): void {
191	  if (liveVoice) {
192	    liveVoice.dispose();
193	    liveVoice = null;
194	  }
195	}

