16	
17	/**
18	 * One Durable Object per sound-design session.
19	 *
20	 * Holds the paused Anthropic conversation between HTTP round trips: the agent's
21	 * turn stops at a tool_use block, and can only be resumed once the browser has
22	 * rendered + analyzed the proposed preset. `pendingToolUseId` is what survives
23	 * that gap — on submitAnalysis we synthesize a tool_result carrying that exact
24	 * id, append it, and call the model again. See PLAN.md "The agent loop protocol".
25	 *
26	 * Two tables rather than one blob: the message log grows unboundedly across chat
27	 * turns and would eventually blow the 128 KiB per-value limit.
28	 */
29	
30	interface Meta {
31	  status: SessionStatus;
32	  target: FeatureSummary | null;
33	  targetInfo: TargetInfo | null;
