83	export class SessionDO extends DurableObject<Env> {
84	  private meta: Meta = freshMeta();
85	  private messages: MessageParam[] = [];
86	
87	  constructor(ctx: DurableObjectState, env: Env) {
88	    super(ctx, env);
89	    ctx.blockConcurrencyWhile(async () => {
90	      this.ctx.storage.sql.exec(
91	        `CREATE TABLE IF NOT EXISTS meta (
92	           id INTEGER PRIMARY KEY CHECK(id = 1),
93	           json TEXT NOT NULL
94	         );`,
95	      );
96	      this.ctx.storage.sql.exec(
