* { box-sizing: border-box; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font: 15px/1.55 ui-sans-serif, system-ui, -apple-system, sans-serif;
}
main { max-width: 1180px; margin: 0 auto; padding: 32px 20px 80px; }

/* Two columns: iterations live in the rail, the instrument stays centre stage. */
.layout { display: grid; grid-template-columns: 300px minmax(0, 1fr); gap: 18px; align-items: start; }

/* The rail scrolls independently so the drop zone and keyboard never move,
   however many iterations pile up. min-height:0 is what actually lets a
   grid/flex child shrink enough for the inner list to scroll. */
.rail {
  position: sticky; top: 24px;
  max-height: calc(100vh - 48px);
  display: flex; flex-direction: column; min-height: 0;
}
.rail > .panel {
  display: flex; flex-direction: column; min-height: 0; overflow: hidden;
  margin-bottom: 0;
}
#attempts {
  overflow-y: auto; min-height: 0; flex: 1;
  margin: 0 -18px -18px; padding: 0 18px 18px;  /* let rows bleed to the panel edge */
  scrollbar-width: thin; scrollbar-color: var(--line) transparent;
}
#attempts::-webkit-scrollbar { width: 8px; }

