/* App shell: the viewport IS the app. Nothing scrolls except the two
   panes that are supposed to, so the instrument never moves under you. */
html, body { height: 100%; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font: 15px/1.55 ui-sans-serif, system-ui, -apple-system, sans-serif;
  overflow: hidden;
}
main {
  height: 100dvh; display: flex; flex-direction: column; min-height: 0;
}

/* Slim top bar, not a page masthead. */
.topbar {
  display: flex; align-items: center; gap: 14px;
  padding: 0 18px; height: 52px; flex: none;
  border-bottom: 1px solid var(--line); background: #191821;
}
.brand { font-size: 15px; font-weight: 650; letter-spacing: -0.01em; }
.brand span { color: var(--accent); }
.topbar .sub { margin: 0; font-size: 13px; }
.topbar .spacer { flex: 1; }

/* Two columns: iterations live in the rail, the instrument stays centre stage. */
.layout {
  flex: 1; min-height: 0;
  display: grid; grid-template-columns: 320px minmax(0, 1fr);
}
.rail {
  min-height: 0; display: flex; flex-direction: column;
  border-right: 1px solid var(--line); background: #191821;
}
.stage {
  min-height: 0; display: flex; flex-direction: column;
}
/* Everything above the keyboard scrolls; the keyboard is docked. */
.stage-scroll { flex: 1; min-height: 0; overflow-y: auto; padding: 18px; }
.dock {
  flex: none; border-top: 1px solid var(--line);
  background: #191821; padding: 12px 18px 16px;
}

